def compute_set_for_roll(ident):
    digits = re.sub(r"\D", "", str(ident or ""))
    tail = int(digits[-3:]) if len(digits) >= 3 else 1
    return ((tail * 17) + 7) % 50 + 1

def q(sql, a=(), one=False, commit=False):
    c = sqlite3.connect(DB); c.row_factory = sqlite3.Row
    cur = c.execute(sql, a); r = cur.fetchone() if one else cur.fetchall()
    if commit: c.commit(); r = cur.lastrowid
    c.close(); return r

def init():
    c = sqlite3.connect(DB)
    c.executescript("""
    CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, ident TEXT UNIQUE, name TEXT, pw TEXT, plain_pw TEXT, role TEXT, batch TEXT, assigned_set INT DEFAULT 1);
    CREATE TABLE IF NOT EXISTS exams(id INTEGER PRIMARY KEY, title TEXT, minutes INT, max_flags INT);
    CREATE TABLE IF NOT EXISTS questions(id INTEGER PRIMARY KEY, eid INT, set_no INT DEFAULT 0, title TEXT, body TEXT, marks REAL, mode TEXT);
    CREATE TABLE IF NOT EXISTS tests(id INTEGER PRIMARY KEY, qid INT, inp TEXT, out TEXT, hidden INT);
    CREATE TABLE IF NOT EXISTS attempts(id INTEGER PRIMARY KEY, uid INT, eid INT, start REAL, done INT DEFAULT 0, UNIQUE(uid,eid));
    CREATE TABLE IF NOT EXISTS subs(id INTEGER PRIMARY KEY, uid INT, qid INT, lang TEXT, code TEXT, score REAL, passed INT, total INT, UNIQUE(uid,qid));
    CREATE TABLE IF NOT EXISTS flags(id INTEGER PRIMARY KEY, uid INT, eid INT, kind TEXT, ts TEXT DEFAULT CURRENT_TIMESTAMP);
    """)
    if not c.execute("SELECT 1 FROM users").fetchone():
        for ident, name, pw, role, batch, aset in SEED_USERS:
            shown_pw = "SHA-256 Protected" if role == "admin" else pw
            c.execute("INSERT OR IGNORE INTO users(ident,name,pw,plain_pw,role,batch,assigned_set) VALUES(?,?,?,?,?,?,?)",
                      (ident.lower(), name, gph(pw), shown_pw, role, batch, aset))
        c.execute("INSERT INTO exams(id,title,minutes,max_flags) VALUES(1,'3rd CSE-5 — Internal Lab Exam-2: Java Programming (50 Anti-Adjacent Question Sets)',60,5)")
        for qitem in SEED_QUESTIONS:
            cur = c.execute("INSERT INTO questions(id,eid,set_no,title,body,marks,mode) VALUES(?,?,?,?,?,?,?)",
                            (qitem["id"], 1, qitem["setNo"], qitem["title"], qitem["body"], qitem["marks"], qitem["mode"]))
            qid = qitem["id"]
            for t in qitem["tests"]:
                c.execute("INSERT INTO tests(qid,inp,out,hidden) VALUES(?,?,?,?)", (qid, t["inp"], t["out"], t["hidden"]))
    c.commit(); c.close()

def me(): return q("SELECT * FROM users WHERE id=?", (session.get("uid"),), one=True) if "uid" in session else None
def need(role):
    def deco(f):
        @functools.wraps(f)
        def w(*a, **k):
            u = me()
            if not u: return redirect("/login")
            if u["role"] != role: abort(403)
            return f(u, *a, **k)
        return w
    return deco

def norm(s): return "\n".join(l.rstrip() for l in s.strip().replace("\r", "").split("\n"))
def limits(java):
    if not resource:
        return None
    def f():
        resource.setrlimit(resource.RLIMIT_CPU, (10, 10))
        resource.setrlimit(resource.RLIMIT_FSIZE, (1 << 20, 1 << 20))
        if not java: resource.setrlimit(resource.RLIMIT_AS, (512 << 20, 512 << 20))
    return f

def run_tests(lang, code, tests):
    d = tempfile.mkdtemp(); env = {"PATH": os.environ.get("PATH", "")}
    try:
        if lang == "python":
            open(d + "/main.py", "w", encoding="utf-8").write(code)
            cmd = ["python3", "main.py"]
        elif lang == "c":
            open(d + "/main.c", "w", encoding="utf-8").write(code)
            p = subprocess.run(["gcc", "main.c", "-o", "main", "-lm"], cwd=d, capture_output=True, text=True, timeout=20)
            if p.returncode: return [dict(ok=False, got="", err="Compile error:\n" + p.stderr[:800])] * len(tests)
            cmd = ["./main"]
        elif lang == "java":
            open(d + "/Main.java", "w", encoding="utf-8").write(code)
            p = subprocess.run(["javac", "Main.java"], cwd=d, capture_output=True, text=True, timeout=30)
            if p.returncode: return [dict(ok=False, got="", err="Compile error:\n" + p.stderr[:800])] * len(tests)
            cmd = ["java", "-Xmx256m", "Main"]
        else:
            return [dict(ok=False, got="", err="Unsupported language")] * len(tests)
        out = []
        for t in tests:
            try:
                p = subprocess.run(cmd, cwd=d, input=t["inp"], capture_output=True, text=True, env=env,
                                   timeout=10 if lang == "java" else 5, preexec_fn=limits(lang == "java"))
                out.append(dict(ok=p.returncode == 0 and norm(p.stdout) == norm(t["out"]), got=p.stdout[:500], err=p.stderr[:500]))
            except subprocess.TimeoutExpired:
                out.append(dict(ok=False, got="", err="Time limit exceeded"))
        return out
    finally:
        shutil.rmtree(d, True)

def grade(qu, res, tests=None):
    p, n = sum(r["ok"] for r in res), len(res)
    if not n:
        return 0.0, 0, 0
    if qu["mode"] == "all":
        s = qu["marks"] if p == n else 0.0
    elif qu["mode"] == "weighted" and tests:
        sp = sum(r["ok"] for r, t in zip(res, tests) if not t["hidden"])
        st = sum(1 for t in tests if not t["hidden"])
        hp = sum(r["ok"] for r, t in zip(res, tests) if t["hidden"])
        ht = sum(1 for t in tests if t["hidden"])
        if st > 0 and ht > 0:
            s = qu["marks"] * (0.30 * (sp / st) + 0.70 * (hp / ht))
        else:
            s = qu["marks"] * p / n
    else:
        s = qu["marks"] * p / n
    return round(s, 2), p, n

def parse_tests(text):
    res = []
    for b in re.split(r"\n-{3,}\n", "\n" + text.replace("\r", "").strip() + "\n"):
        b = b.strip("\n")
        if "=>" not in b: continue
        hidden = b.startswith("#hidden"); b = b.split("\n", 1)[1] if hidden and "\n" in b else b
        inp, out = re.split(r"\n?=>\n?", b, 1)
        res.append((inp.strip() + "\n", out.strip(), int(hidden)))
    return res

